// Runnable demo: atomic DB write + outbox row, then at-least-once relay + idempotent consumer.
package com.bank.transfer.demo;

import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.logging.ConsoleHandler;
import java.util.logging.Formatter;
import java.util.logging.Level;
import java.util.logging.LogRecord;
import java.util.logging.Logger;

public class OutboxDemo {

    private static final Logger log = Logger.getLogger("Outbox");
    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        log.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        AccountRepository accounts = new AccountRepository();
        accounts.save(new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000")));
        accounts.save(new Account("CUR3001", "Priya Sharma", new BigDecimal("250000")));
        OutboxRepository outbox = new OutboxRepository();
        TransferService service = new TransferService(accounts, outbox);

        log.info("=== one local DB transaction: debit + credit + outbox insert ===");
        service.transfer("SAV2001", "CUR3001", new BigDecimal("50000"));
        log.info(() -> "Rajesh balance=Rs." + accounts.find("SAV2001").balance);
        log.info(() -> "Priya balance=Rs." + accounts.find("CUR3001").balance);

        log.info("=== relay publishes unsent outbox rows (at-least-once) ===");
        NotificationConsumer consumer = new NotificationConsumer();
        OutboxRelay relay = new OutboxRelay(outbox, consumer);
        relay.pollAndPublish(/*simulateCrashBeforeMarkSent*/ true);  // publishes, then "crash"
        relay.pollAndPublish(/*simulateCrashBeforeMarkSent*/ false); // republish same event
        log.info(() -> "notifications delivered (deduped) = " + consumer.deliveredCount());
    }
}

// ─── Would be in Account.java ───
class Account {
    final String id; final String holderName; BigDecimal balance;
    Account(String id, String holderName, BigDecimal balance) {
        this.id = id; this.holderName = holderName; this.balance = balance;
    }
    void debit(BigDecimal a) { balance = balance.subtract(a); }
    void credit(BigDecimal a) { balance = balance.add(a); }
}

// ─── Would be in OutboxEvent.java ───
class OutboxEvent {
    final String eventId; final String type; final String payload; boolean sent;
    OutboxEvent(String eventId, String type, String payload) {
        this.eventId = eventId; this.type = type; this.payload = payload; this.sent = false;
    }
}

// ─── Would be in AccountRepository.java ───
class AccountRepository {
    private final Map<String, Account> store = new LinkedHashMap<>();
    void save(Account a) { store.put(a.id, a); }
    Account find(String id) { return store.get(id); }
}

// ─── Would be in OutboxRepository.java ───
class OutboxRepository {
    private final List<OutboxEvent> rows = new ArrayList<>();
    void insert(OutboxEvent e) { rows.add(e); }          // part of the local DB tx
    List<OutboxEvent> findUnsent() {
        List<OutboxEvent> out = new ArrayList<>();
        for (OutboxEvent e : rows) if (!e.sent) out.add(e);
        return out;
    }
    void markSent(OutboxEvent e) { e.sent = true; }
}

// ─── Would be in TransferService.java ───
// @Transactional in a real app: debit + credit + outbox insert = ONE local tx.
class TransferService {
    private static final Logger log = Logger.getLogger("Outbox");
    private final AccountRepository accounts;
    private final OutboxRepository outbox;
    private int seq = 0;
    TransferService(AccountRepository accounts, OutboxRepository outbox) {
        this.accounts = accounts; this.outbox = outbox;
    }

    // @Transactional
    void transfer(String fromId, String toId, BigDecimal amount) {
        Account from = accounts.find(fromId);
        Account to = accounts.find(toId);
        from.debit(amount);
        to.credit(amount);
        accounts.save(from);
        accounts.save(to);
        // Same local transaction: the event is written to the outbox, not to Kafka.
        String eventId = "EVT-" + (++seq);
        String payload = "{\"from\":\"" + fromId + "\",\"to\":\"" + toId
                + "\",\"amount\":" + amount + "}";
        outbox.insert(new OutboxEvent(eventId, "TransferCompleted", payload));
        log.info(() -> "committed transfer + outbox row " + eventId + " in one DB tx");
        // COMMIT here: balances and outbox row persist together atomically.
    }
}

// ─── Would be in OutboxRelay.java ───
// Separate process: reads unsent rows, publishes to Kafka, marks sent. At-least-once.
class OutboxRelay {
    private static final Logger log = Logger.getLogger("Outbox");
    private final OutboxRepository outbox;
    private final NotificationConsumer consumer; // stands in for Kafka + downstream
    OutboxRelay(OutboxRepository outbox, NotificationConsumer consumer) {
        this.outbox = outbox; this.consumer = consumer;
    }

    void pollAndPublish(boolean simulateCrashBeforeMarkSent) {
        for (OutboxEvent e : outbox.findUnsent()) {
            log.info(() -> "relay publishing " + e.eventId + " to Kafka topic transfer.completed");
            consumer.onEvent(e.eventId, e.payload);   // "publish" to Kafka → consumer
            if (simulateCrashBeforeMarkSent) {
                log.severe(() -> "CRASH before markSent(" + e.eventId + "); will republish");
                return;  // row stays unsent → republished next poll
            }
            outbox.markSent(e);
            log.info(() -> "marked sent " + e.eventId);
        }
    }
}

// ─── Would be in NotificationConsumer.java ───
// Idempotent: dedups by eventId so at-least-once republish is harmless.
class NotificationConsumer {
    private static final Logger log = Logger.getLogger("Outbox");
    private final Set<String> seen = new HashSet<>();
    private int delivered = 0;
    void onEvent(String eventId, String payload) {
        if (!seen.add(eventId)) {
            log.warning(() -> "duplicate event " + eventId + " ignored (idempotent)");
            return;
        }
        delivered++;
        log.info(() -> "notification sent for " + eventId + " payload=" + payload);
    }
    int deliveredCount() { return delivered; }
}

// ─── Would be in BankLogFormatter.java ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
